import functools

def logger(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f'Calling {func.__name__}')
        result = func(*args, **kwargs)
        print(f'Done with {func.__name__}')
        return result
    return wrapper

@logger
def greet(name):
    print(f'Hello, {name}!')

greet('Vaathiyaar')
